import pytest
from playwright.sync_api import expect
from sites.saucedemo.pages.login_page import LoginPage
from sites.saucedemo.pages.inventory_page import InventoryPage
from sites.saucedemo.pages.cart_page import CartPage
from sites.saucedemo.pages.checkout_page import CheckoutPage
from sites.saucedemo.config import Config


class TestCheckoutRequiredFields:

    @pytest.fixture(autouse=True)
    def login(self, page):
        login_page = LoginPage(page)
        login_page.navigate()
        login_page.login(Config.STANDARD_USER, Config.PASSWORD)

    @pytest.fixture(autouse=True)
    def go_to_checkout_step_one(self, page, login):
        inventory_page = InventoryPage(page)
        inventory_page.add_item_to_cart("Sauce Labs Backpack")
        inventory_page.go_to_cart()

        cart_page = CartPage(page)
        cart_page.proceed_to_checkout()

    def test_missing_last_name_shows_error(self, page):
        """AC-1: Continuing with first name and postal code filled but last name empty shows the error "Error: Last Name is required"."""
        checkout_page = CheckoutPage(page)
        checkout_page.fill_customer_info("John", "", "V5C 0A3")
        checkout_page.continue_to_overview()

        assert checkout_page.get_error_message() == "Error: Last Name is required"

    def test_missing_postal_code_shows_error(self, page):
        """AC-2: Continuing with first and last name filled but postal code empty shows the error "Error: Postal Code is required"."""
        checkout_page = CheckoutPage(page)
        checkout_page.fill_customer_info("John", "Doe", "")
        checkout_page.continue_to_overview()

        assert checkout_page.get_error_message() == "Error: Postal Code is required"

    def test_all_fields_filled_moves_to_overview(self, page):
        """AC-3: Continuing with all three fields filled moves the user to the checkout overview page (`/checkout-step-two.html`)."""
        checkout_page = CheckoutPage(page)
        checkout_page.fill_customer_info("John", "Doe", "V5C 0A3")
